def m(i, fmt, diff, stem, options, ans, expl, **kw):
    d = {"id":"inf-t9-m-%02d"%i, "format":fmt, "topic":"inference-t9", "diff":diff,
         "stem":stem, "options":options, "answer":ans, "explanation":expl}
    d.update(kw); return d

